import{uid as t,today as s}from"../sidebar/ui/Dom.js";export const SUB_STATUS=[["disiapkan","Disiapkan"],["terkirim","Terkirim"],["ditinjau","Ditinjau"],["diminta","Diminta revisi"],["diterima","Diterima"],["ditolak","Ditolak"]];export class SubmissionService{constructor(t,s,i){this.store=t,this.projects=s,this.bus=i,this.items=[],this.trash=null}key(t=this.projects.activeId){return`submissions:${t}`}async load(t=this.projects.activeId){return this.items=await this.store.get(this.key(t),[])||[],this.items}async save(){await this.store.set(this.key(),this.items),this.bus.emit("project.changed",{part:"submissions"})}async add(s={}){const i={id:t("sub"),publisher:"Penerbit baru",contact:"",sentAt:"",status:"disiapkan",note:"",nextAt:"",...s};return this.items.push(i),await this.save(),i}async update(t,s){const i=this.items.find(s=>s.id===t);return i?(Object.assign(i,s),await this.save(),i):null}async markSent(t){return this.update(t,{status:"terkirim",sentAt:s()})}async remove(t){const s=Array.isArray(t)?t:[t];return this.trash=this.items.filter(t=>s.includes(t.id)),this.items=this.items.filter(t=>!s.includes(t.id)),await this.save(),this.trash}async undo(){if(!this.trash)return null;this.items.push(...this.trash);const t=this.trash;return this.trash=null,await this.save(),t}dueSoon(t=7){const s=Date.now()+864e5*t;return this.items.filter(t=>t.nextAt&&new Date(t.nextAt).getTime()<=s&&!["diterima","ditolak"].includes(t.status))}stats(){const t={};for(const[s]of SUB_STATUS)t[s]=0;for(const s of this.items)t[s.status]=(t[s.status]||0)+1;const s=this.items.filter(t=>t.sentAt),i=this.items.filter(t=>["diterima","ditolak","diminta"].includes(t.status));return{total:this.items.length,by:t,sent:s.length,answerRate:s.length?i.length/s.length:0}}queryLetter(t,s){const i=t||{};return[`Kepada ${s?.publisher||"Redaksi"},`,"",`Saya ${i.author||"(nama penulis)"}, mengajukan naskah "${i.title||"(judul)"}" (${i.genre||"genre"}), panjang sekitar ${Math.round((i.targetWords||7e4)/1e3)} ribu kata.`,"",`Premis: ${i.premise||"(satu paragraf premis)"}`,"","Naskah lengkap tersedia atas permintaan. Tiga bab pertama dan sinopsis saya lampirkan.","","Terima kasih atas waktu dan pertimbangan Bapak/Ibu.",`Hormat saya,\n${i.author||"(nama penulis)"}`].join("\n")}}